                CardId::Forest,
                CardId::Forest,
                CardId::Forest,
                CardId::Forest,
            ],
        )
        .library(P0, &[CardId::Forest; 20])
        .library(P1, &[CardId::Forest; 20])
        .main(P0, Step::PrecombatMain)
        .build();
    let a = add_perm(&mut g, P0, CardId::GrizzlyBears);
    let b = add_perm(&mut g, P1, CardId::RuneclawBear);
