            return;
        }
        if card == CardId::AyulaQueenAmongBears && event == TriggerEvent::AnotherCreatureEnters {
            let seq = self.state.next_trigger_seq;
            self.state.next_trigger_seq += 1;
            self.state.trigger_queue.push(TriggerRef {
                source,
                card,
                controller,
                ability: 0,
                seq,
                spell_mana_value: 0,
                affected: None,
            });
            return;
