        let mut queue = std::mem::take(&mut self.state.trigger_queue);
        // A trigger whose controller left the game is never put on the stack
        // (CR 800.4a).
        queue.retain(|trigger| self.state.is_live(trigger.controller));
        if queue.is_empty() {
            return false;
