        .hand(P0, &[card("Werebear")])
        .battlefield(P0, &board)
        .library(P0, &[CardId::Forest; 8])
        .library(P1, &[CardId::Forest; 8])
        .main(P0, Step::PrecombatMain)
        .build();
    let werebear = hand_card(&g, P0, card("Werebear"));
